import java.io._
import java.util.Base64
import java.util.zip.{GZIPInputStream, GZIPOutputStream}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

/**
 * High-performance caching layer with compression support.
 * Supports both in-memory and serialized (persistent) cache entries.
 */
object CacheConfig {
  val MAX_ENTRY_SIZE: Int = 1024 * 1024 // 1MB
  val MAX_ENTRIES: Int = 10000
  val COMPRESSION_THRESHOLD: Int = 512
  val ALLOWED_PREFIXES: Set[String] = Set("session:", "user:", "config:", "data:")
}

sealed trait CacheEntry
case class RawEntry(data: Array[Byte], createdAt: Long) extends CacheEntry
case class CompressedEntry(compressed: Array[Byte], originalSize: Int, createdAt: Long) extends CacheEntry

trait Serializer[T] {
  def serialize(obj: T): Array[Byte]
  def deserialize(bytes: Array[Byte]): T
}

object DefaultSerializer extends Serializer[Any] {
  def serialize(obj: Any): Array[Byte] = {
    val baos = new ByteArrayOutputStream()
    val oos = new ObjectOutputStream(baos)
    try {
      oos.writeObject(obj)
      oos.flush()
      baos.toByteArray
    } finally {
      oos.close()
      baos.close()
    }
  }

  def deserialize(bytes: Array[Byte]): Any = {
    val bais = new ByteArrayInputStream(bytes)
    val ois = new ObjectInputStream(bais)
    try {
      ois.readObject()
    } finally {
      ois.close()
      bais.close()
    }
  }
}

object CompressionUtil {
  def compress(data: Array[Byte]): Array[Byte] = {
    val baos = new ByteArrayOutputStream()
    val gzip = new GZIPOutputStream(baos)
    try {
      gzip.write(data)
      gzip.finish()
      baos.toByteArray
    } finally {
      gzip.close()
      baos.close()
    }
  }

  def decompress(data: Array[Byte]): Array[Byte] = {
    val bais = new ByteArrayInputStream(data)
    val gzip = new GZIPInputStream(bais)
    try {
      val buffer = new Array[Byte](4096)
      val baos = new ByteArrayOutputStream()
      var len = gzip.read(buffer)
      while (len > 0) {
        baos.write(buffer, 0, len)
        len = gzip.read(buffer)
      }
      baos.toByteArray
    } finally {
      gzip.close()
      bais.close()
    }
  }
}

/**
 * Validates cache keys to prevent injection attacks.
 */
object KeyValidator {
  private val VALID_KEY_PATTERN = """^[a-zA-Z0-9:_\-\.]{1,256}$""".r

  def isValidKey(key: String): Boolean = {
    key != null && VALID_KEY_PATTERN.findFirstIn(key).isDefined &&
      CacheConfig.ALLOWED_PREFIXES.exists(key.startsWith)
  }
}

/**
 * Thread-safe distributed cache client.
 * Supports importing cache snapshots from trusted peers.
 */
class CacheService {
  private val store: mutable.Map[String, CacheEntry] = mutable.Map.empty
  private val serializer: Serializer[Any] = DefaultSerializer

  def put(key: String, value: Any): Either[String, Unit] = synchronized {
    if (!KeyValidator.isValidKey(key)) {
      Left(s"Invalid cache key: rejected by policy")
    } else if (store.size >= CacheConfig.MAX_ENTRIES) {
      Left("Cache capacity exceeded")
    } else {
      val bytes = serializer.serialize(value)
      if (bytes.length > CacheConfig.MAX_ENTRY_SIZE) {
        Left("Entry exceeds maximum size")
      } else if (bytes.length > CacheConfig.COMPRESSION_THRESHOLD) {
        val compressed = CompressionUtil.compress(bytes)
        store.put(key, CompressedEntry(compressed, bytes.length, System.currentTimeMillis()))
        Right(())
      } else {
        store.put(key, RawEntry(bytes, System.currentTimeMillis()))
        Right(())
      }
    }
  }

  def get(key: String): Either[String, Any] = synchronized {
    if (!KeyValidator.isValidKey(key)) {
      Left("Invalid cache key")
    } else {
      store.get(key) match {
        case Some(RawEntry(data, _)) =>
          Right(serializer.deserialize(data))
        case Some(CompressedEntry(compressed, _, _)) =>
          val decompressed = CompressionUtil.decompress(compressed)
          Right(serializer.deserialize(decompressed))
        case None =>
          Left("Key not found")
      }
    }
  }

  /**
   * Import a cache snapshot from a peer node.
   * The snapshot is a Base64-encoded, GZIP-compressed serialized Map.
   * Only accepts snapshots with valid structure.
   */
  def importSnapshot(base64Snapshot: String): Either[String, Int] = {
    Try {
      val decoded = Base64.getDecoder.decode(base64Snapshot)
      if (decoded.length > CacheConfig.MAX_ENTRY_SIZE * 10) {
        throw new IllegalArgumentException("Snapshot too large")
      }
      val decompressed = CompressionUtil.decompress(decoded)
      // Deserialize the snapshot map
      val snapshotData = serializer.deserialize(decompressed)
      snapshotData match {
        case entries: Map[String @unchecked, Array[Byte] @unchecked] =>
          var imported = 0
          entries.foreach { case (key, value) =>
            if (KeyValidator.isValidKey(key)) {
              synchronized {
                if (store.size < CacheConfig.MAX_ENTRIES) {
                  store.put(key, RawEntry(value, System.currentTimeMillis()))
                  imported += 1
                }
              }
            }
          }
          imported
        case _ =>
          throw new IllegalArgumentException("Invalid snapshot format")
      }
    } match {
      case Success(count) => Right(count)
      case Failure(e: IllegalArgumentException) => Left(e.getMessage)
      case Failure(_) => Left("Failed to import snapshot")
    }
  }

  /**
   * Export current cache as a portable snapshot.
   */
  def exportSnapshot(): String = synchronized {
    val entries: Map[String, Array[Byte]] = store.collect {
      case (key, RawEntry(data, _)) => key -> data
      case (key, CompressedEntry(compressed, _, _)) =>
        key -> CompressionUtil.decompress(compressed)
    }.toMap
    val serialized = serializer.serialize(entries)
    val compressed = CompressionUtil.compress(serialized)
    Base64.getEncoder.encodeToString(compressed)
  }

  def size: Int = synchronized { store.size }
  def clear(): Unit = synchronized { store.clear() }
}
